function greetable(obj) {
  if (typeof obj.Greet === "function") return obj.Greet();
  return "不是 Greetable";
}
const dog = { Greet() { return "Woof"; } };
const robot = { Greet() { return "Beep"; }, id: 1 };
const rock = {};
console.log(greetable(dog));
console.log(greetable(robot));
console.log(greetable(rock));
